// Parsea la respuesta de Claude y la combina con los datos del prospecto
const claudeRaw = $json;

// Intentar obtener el prospecto original via item pairing
let prospecto;
try {
  prospecto = $('03 · Lista de Prospectos').item.json;
} catch(e) {
  prospecto = {};
}

// Extraer el texto de la respuesta de Claude
let text = '';
try {
  text = claudeRaw.content[0].text.trim();
} catch(e) {
  text = '';
}

// Parsear JSON — Claude a veces añade texto antes/después o usa nombres en inglés
let emailData = {};
try {
  const match = text.match(/\{[\s\S]*\}/);
  if (match) {
    emailData = JSON.parse(match[0]);
  }
} catch(e) {
  // si falla, emailData queda como objeto vacío y usamos fallbacks abajo
}

// Normalizar campos: Claude puede devolver 'body', 'email_body', 'cuerpo', etc.
const asunto = emailData.asunto || emailData.subject || emailData.email_subject || '(asunto no generado)';
const cuerpo = emailData.cuerpo || emailData.body || emailData.email_body || emailData.email || text || '(email no generado)';
const angulo_usado = emailData.angulo_usado || emailData.angle || emailData.angulo || emailData.reason || '(sin ángulo)';

// Calcular puntuación de oportunidad (1-10)
let score = 5;
if (!prospecto.tiene_pixel_meta && !prospecto.gasta_en_ads) {
  score = 9;
} else if (prospecto.tiene_pixel_meta && !prospecto.gasta_en_ads) {
  score = 7;
} else if (prospecto.gasta_en_ads && prospecto.ads_estimado && prospecto.ads_estimado.includes('500')) {
  score = 6;
} else if (prospecto.gasta_en_ads) {
  score = 4;
}
if (prospecto.instagram_followers > 25000) score = Math.min(10, score + 1);
else if (prospecto.instagram_followers > 10000) score = Math.min(10, score + 0.5);
score = Math.round(score);

// Badge de estado
let badge_estado, badge_color;
if (!prospecto.gasta_en_ads) {
  badge_estado = 'Sin ads';
  badge_color = 'red';
} else if (prospecto.ads_estimado && (prospecto.ads_estimado.includes('500') || prospecto.ads_estimado.includes('menos'))) {
  badge_estado = 'Ads bajo presupuesto';
  badge_color = 'orange';
} else {
  badge_estado = 'Con ads activos';
  badge_color = 'green';
}

// Color indicador de actividad en Instagram
let actividad_ig_color;
const ultima = prospecto.ultima_publicacion_ig || '';
if (ultima === 'hoy' || ultima === 'ayer') {
  actividad_ig_color = 'green';
} else if (ultima.includes('días')) {
  actividad_ig_color = 'yellow';
} else {
  actividad_ig_color = 'red';
}

return [{
  json: {
    ...prospecto,
    asunto,
    cuerpo,
    angulo_usado,
    oportunidad_score: score,
    badge_estado,
    badge_color,
    actividad_ig_color
  }
}];

// El HTML está disponible como archivo binario en el nodo anterior.
// Haz clic en el nodo 07 → pestaña "Binary" → botón de descarga de "data".
// Guarda el archivo y ábrelo en Chrome.

return [{
  json: {
    estado: '✅ Dashboard generado correctamente',
    paso_final: 'En el nodo 07, abre la pestaña Binary y descarga autoprospect_demo.html',
    prospectos: $json.prospectos_count,
    sin_ads: $json.sin_ads,
    generado_en: $json.generado_en
  }
}];
